#!/usr/bin/env python3
"""maze.py: read a grid of '#' and '.' with S and E on stdin, print the
shortest 4-neighbour path length from S to E, or -1 if unreachable.

Fast path: a tiny C BFS compiled once with gcc/cc and cached next to this
script (or in the temp dir). Fallback: pure-Python BFS, same answer.
"""
import sys, os

C_SRC = r"""
#include <stdint.h>
#include <stdlib.h>
/* g: n bytes, rows separated by one wall byte, padded by a wall row at each
   end. Open cells are '.', 'S', 'E'; everything else is a wall. */
long bfs(unsigned char *g, long n, long stride, long s, long e) {
    long i, head = 0, tail = 0, lev, d = 0;
    int32_t *q;
    int32_t off[4];
    if (n >= 2147483647L) return -2;
    for (i = 0; i < n; i++) {
        unsigned char c = g[i];
        g[i] = (c == '.' || c == 'S' || c == 'E');
    }
    q = (int32_t *)malloc(sizeof(int32_t) * (size_t)n);
    if (!q) return -2;
    off[0] = 1; off[1] = -1; off[2] = (int32_t)stride; off[3] = -(int32_t)stride;
    g[s] = 0; q[tail++] = (int32_t)s;
    while (head < tail) {
        d++;
        lev = tail;
        for (; head < lev; head++) {
            int32_t c = q[head];
            int k;
            for (k = 0; k < 4; k++) {
                int32_t nb = c + off[k];
                if (g[nb]) {
                    if (nb == e) { free(q); return d; }
                    g[nb] = 0;
                    q[tail++] = nb;
                }
            }
        }
    }
    free(q);
    return -1;
}
"""


def load_lib():
    try:
        import ctypes, hashlib, subprocess, tempfile
        tag = hashlib.md5(C_SRC.encode()).hexdigest()[:12]
        name = "_mazebfs_%s.so" % tag
        here = os.path.dirname(os.path.abspath(__file__))
        dirs = [here, tempfile.gettempdir()]
        lib = None
        for d in dirs:
            p = os.path.join(d, name)
            if os.path.exists(p):
                try:
                    lib = ctypes.CDLL(p)
                    break
                except OSError:
                    pass
        if lib is None:
            for d in dirs:
                p = os.path.join(d, name)
                tmp = "%s.%d.tmp" % (p, os.getpid())
                src = tmp + ".c"
                try:
                    with open(src, "w") as f:
                        f.write(C_SRC)
                    for cc in ("gcc", "cc"):
                        try:
                            r = subprocess.run(
                                [cc, "-O2", "-shared", "-fPIC", "-o", tmp, src],
                                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                        except OSError:
                            continue
                        if r.returncode == 0:
                            os.replace(tmp, p)
                            lib = ctypes.CDLL(p)
                            break
                except OSError:
                    pass
                finally:
                    for junk in (src, tmp):
                        try:
                            os.remove(junk)
                        except OSError:
                            pass
                if lib is not None:
                    break
        if lib is None:
            return None
        lib.bfs.restype = ctypes.c_long
        lib.bfs.argtypes = [ctypes.c_void_p, ctypes.c_long, ctypes.c_long,
                            ctypes.c_long, ctypes.c_long]
        return lib, ctypes
    except Exception:
        return None


def py_bfs(g, stride, s, e):
    # g: bytearray, open cells are '.', 'S', 'E'
    OPEN = (46, 83, 69)
    g[s] = 35
    frontier = [s]
    d = 0
    offs = (1, -1, stride, -stride)
    while frontier:
        d += 1
        nxt = []
        push = nxt.append
        for c in frontier:
            for o in offs:
                nb = c + o
                if g[nb] in OPEN:
                    if nb == e:
                        return d
                    g[nb] = 35
                    push(nb)
        frontier = nxt
    return -1


def solve(data, force_py=False):
    if b"\r" in data:
        data = data.replace(b"\r", b"")
    lines = data.split(b"\n")
    while lines and not lines[-1]:
        lines.pop()
    if not lines:
        return -1
    w = max(map(len, lines))
    if min(map(len, lines)) != w:
        lines = [ln.ljust(w, b"#") for ln in lines]
    stride = w + 1
    g = bytearray(stride)
    g += b"\n".join(lines)
    g += b"\n"
    g += bytes(stride)
    s = g.find(b"S")
    e = g.find(b"E")
    if s < 0 or e < 0:
        return -1
    if not force_py:
        lib = load_lib()
        if lib is not None:
            lib, ctypes = lib
            n = len(g)
            buf = (ctypes.c_ubyte * n).from_buffer(g)
            r = lib.bfs(ctypes.addressof(buf), n, stride, s, e)
            if r != -2:
                return r
            del buf
    return py_bfs(g, stride, s, e)


def main():
    data = sys.stdin.buffer.read()
    force_py = os.environ.get("MAZE_PURE_PY") == "1"
    sys.stdout.write("%d\n" % solve(data, force_py))


if __name__ == "__main__":
    main()

import subprocess, sys, time, os
here = os.path.dirname(os.path.abspath(__file__))
os.chdir(here)
def run(prog, path):
    with open(path, 'rb') as f:
        return subprocess.run([sys.executable, prog], stdin=f, capture_output=True, timeout=25).stdout.decode().strip()
try:
    # correctness: small cases against the reference, big case against stored answer
    for p in ('s.txt', 't.txt'):
        if run('maze.py', p) != run('ref.py', p):
            print(0); sys.exit(0)
    want = open('big.ans').read().strip()
    N = 10
    t = time.perf_counter()
    for _ in range(N):
        if run('maze.py', 'big.txt') != want:
            print(0); sys.exit(0)
    dt = time.perf_counter() - t
    print(round(N / dt, 3))  # runs per second on the 2000x2000 maze
except Exception:
    print(0)
